40	const ALLOWED_BUTTON_TYPES: [&str; 3] = ["submit", "button", "reset"];
41	
42	pub struct UseButtonTypeState {
43	    missing_prop: bool,
44	}
45	
46	impl Rule for UseButtonType {
47	    type Query = Ast<AnyHtmlElement>;
48	    type State = UseButtonTypeState;
49	    type Signals = Option<Self::State>;
50	    type Options = UseButtonTypeOptions;
51	
52	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
53	        let element = ctx.query();
54	
55	        if !is_button_element(element, ctx) {
56	            return None;
57	        }
58	
59	        let type_attribute = element.find_attribute_by_name("type");
60	
61	        // If no regular attribute found, check for Svelte shorthand syntax
62	        if type_attribute.is_none() {
63	            // Check if there's a shorthand attribute like {type}
64	            if has_dynamic_attribute(element, "type") {
65	                // We can't validate the runtime value, but the attribute will be provided
66	                // Assume it's valid since we can't determine the value
67	                return None;
68	            }
69	            // No regular attribute and no shorthand - missing type attribute
70	            return Some(UseButtonTypeState { missing_prop: true });
71	        }
72	
73	        let attribute = type_attribute?;
74	
75	        let Some(initializer) = attribute.initializer() else {
76	            return Some(UseButtonTypeState {
77	                missing_prop: false,
78	            });
79	        };
80	
81	        let value = initializer.value().ok()?;
82	
83	        // If the value is a dynamic expression (e.g., {foo} in Svelte), we can't validate it,
84	        // so we assume it's valid to avoid false positives.
85	        // We only validate static string values.
86	        if value.as_html_string().is_some() {
87	            // Static string value - validate it
88	            if let Some(string_value) = value.string_value()
89	                && ALLOWED_BUTTON_TYPES.contains(&&*string_value)
90	            {
91	                return None;
92	            }
93	            // Invalid static value
94	            return Some(UseButtonTypeState {
95	                missing_prop: false,
96	            });
97	        }
98	
99	        // Dynamic expression - assume valid
100	        None
101	    }
102	
103	    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
104	        Some(RuleDiagnostic::new(rule_category!(),
105	            ctx.query().range(),
106	            if state.missing_prop {
107	                markup! {
108	                    "Provide an explicit "<Emphasis>"type"</Emphasis>" attribute for the "<Emphasis>"button"</Emphasis>" element."
109	                }
110	            } else {
111	                markup!{
112	                    "Provide a valid "<Emphasis>"type"</Emphasis>" attribute for the "<Emphasis>"button"</Emphasis>" element."
113	                }
114	            }
115	        )
116	            .note(markup! {
117	                "The default "<Emphasis>"type"</Emphasis>" of a button is "<Emphasis>"submit"</Emphasis>", which causes the submission of a form when placed inside a `form` element."
118	            })
119	            .note(
120	            markup! {
121	
122	                "Allowed button types are: "<Emphasis>"submit"</Emphasis>", "<Emphasis>"button"</Emphasis>" or "<Emphasis>"reset"</Emphasis>""
123	            }
124	        ))
125	    }
126	}
