128	fn is_button_element(element: &AnyHtmlElement, ctx: &RuleContext<UseButtonType>) -> bool {
129	    let Some(element_name) = element.name() else {
130	        return false;
131	    };
132	
133	    let source_type = ctx.source_type::<HtmlFileSource>();
134	
135	    // In HTML files: case-insensitive (BUTTON, Button, button all match)
136	    // In component frameworks (Vue, Svelte, Astro): case-sensitive (only "button" matches)
137	    // This means <Button> in Vue/Svelte is treated as a component and ignored
138	    if source_type.is_html() {
139	        element_name.text().eq_ignore_ascii_case("button")
140	    } else {
141	        element_name.text() == "button"
142	    }
143	}
