145	/// Checks if a dynamic attribute (shorthand or directive) exists for the given name.
146	/// For example, `<button {type}>` (Svelte), `<button :type="foo">` (Vue), or `<button v-bind:type="foo">` (Vue).
147	fn has_dynamic_attribute(element: &AnyHtmlElement, name: &str) -> bool {
148	    let Some(attributes) = element.attributes() else {
149	        return false;
150	    };
151	
152	    attributes
153	        .iter()
154	        .find_map(|attr| {
155	            // Check if this is a HtmlSingleTextExpression (Svelte shorthand syntax)
156	            if let Some(single_expr) = attr.as_html_attribute_single_text_expression() {
157	                // Check if the expression text matches the attribute name we're looking for
158	                let expression = single_expr.expression().ok()?.html_literal_token().ok()?;
159	                return if expression.text() == name {
160	                    Some(())
161	                } else {
162	                    None
163	                };
164	            } else if let Some(vue_directive) = attr.as_any_vue_directive() {
165	                // Check for v-bind:type="foo" (longhand)
166	                let directive_arg = if let Some(dir) = vue_directive.as_vue_directive()
167	                    && dir.name_token().ok()?.text_trimmed() == "v-bind"
168	                {
169	                    dir.arg()
170	                } else if let Some(dir) = vue_directive.as_vue_v_bind_shorthand_directive() {
171	                    dir.arg().ok()
172	                } else {
173	                    None
174	                }?;
175	
176	                let name_token = directive_arg
177	                    .arg()
178	                    .ok()?
179	                    .as_vue_static_argument()?
180	                    .name_token()
181	                    .ok()?;
182	                if name_token.text_trimmed() == name {
183	                    return Some(());
184	                }
185	            }
186	            None
187	        })
188	        .is_some()
189	}
