161	                            .is_ok_and(|t| t.text_trimmed().eq_ignore_ascii_case("v-bind"));
162	                        is_bind
163	                            && d.arg()
164	                                .and_then(|arg| arg.arg().ok())
165	                                .and_then(|arg| arg.as_vue_static_argument().cloned())
166	                                .and_then(|s| s.name_token().ok())
167	                                .is_some_and(|t| {
168	                                    t.text_trimmed().eq_ignore_ascii_case(name_to_lookup)
169	                                })
