    type State = UseValidAnchorState;
    type Signals = Option<Self::State>;
    type Options = UseValidAnchorOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        // Check if the element is an anchor tag.
        // In HTML files, tag names are case-insensitive.
        // In component frameworks (Vue, Svelte, Astro), only lowercase is checked, so
        // PascalCase components such as `<Link>` are ignored.
        let element_name = node.name()?;
        let source_type = ctx.source_type::<HtmlFileSource>();
        let is_anchor = if source_type.is_html() {
            element_name.text().eq_ignore_ascii_case("a")
        } else {
            element_name.text() == "a"
        };
        if !is_anchor {
            return None;
        }

        let href_attribute = node.find_attribute_by_name("href");

