        // valid, dynamically-provided `href`.
        let has_href_binding = node
            .find_attribute_or_vue_binding("href")
            .is_some_and(|attr| matches!(attr, AnyHtmlAttribute::AnyVueDirective(_)));

        // Only the standard `onclick` attribute is treated as an event handler.
        // Vue-style event directives (e.g. `@click`) are not recognized here.
        let onclick_attribute = if source_type.is_vue() {
            None
        } else {
            node.find_attribute_by_name("onclick")
        };

        match (href_attribute, onclick_attribute) {
            (Some(href_attribute), Some(onclick_attribute)) => {
                if is_valid_href(&href_attribute) {
                    None
                } else {
                    Some(UseValidAnchorState::CantBeAnchor(onclick_attribute.range()))
                }
            }
            (Some(href_attribute), None) => {
                if is_valid_href(&href_attribute) {
                    None
                } else {
                    Some(UseValidAnchorState::IncorrectHref(href_attribute.range()))
                }
            }
            (None, Some(onclick_attribute)) => {
                Some(UseValidAnchorState::CantBeAnchor(onclick_attribute.range()))
            }
            (None, None) => {
                if has_href_binding {
                    None
                } else {
